// Auto-checks a bankroll bet's result against a real final score, for bets
// whose market/pick text was generated by this site's own "log this bet"
// links (public/app.js's logBetHref/renderHandicapRow, value-picks.html's
// logBetHref) — a fixed, known vocabulary of market/pick strings, not
// free-form text. A hand-typed bet (or one in a market/format this doesn't
// recognize) is never guessed at: settleBet returns null rather than force
// a result, exactly like a fixture/date/score match that can't be found.
//
// Bankroll only has three settleable states (won/lost/void) — no half-win/
// half-loss like the Results page's Asian Handicap grading does. A quarter
// line (e.g. -0.75) that actually lands on a half-state is therefore left
// for the user to resolve by hand rather than rounded either direction,
// which would misstate real P/L; only a clean win/loss/push is auto-set.

function num(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

// "2-1" -> { homeGoals: 2, awayGoals: 1 }. Only ever a plain final-score
// string (see src/results/accuracy.js's `score` field) — anything else
// (null, "postponed", etc.) yields null.
function parseScore(scoreStr) {
  const m = /^(\d+)\s*-\s*(\d+)$/.exec(String(scoreStr || '').trim());
  return m ? { homeGoals: Number(m[1]), awayGoals: Number(m[2]) } : null;
}

// Same whole/half/quarter-line split as src/services/asianHandicap.js's
// settleLine — duplicated here (small, pure, no shared runtime between
// server and browser) rather than imported. `marginForSide` is the picked
// side's own goal margin (positive = that side won by that many).
function settleWholeOrHalfLine(line, marginForSide) {
  const adjusted = marginForSide + line;
  if (adjusted > 0) return 1;
  if (adjusted < 0) return -1;
  return 0;
}
function settleHandicapLine(line, marginForSide) {
  if (!Number.isFinite(line) || !Number.isFinite(marginForSide)) return null;
  const frac = ((line % 1) + 1) % 1;
  const isQuarter = Math.abs(frac - 0.25) < 1e-9 || Math.abs(frac - 0.75) < 1e-9;
  if (!isQuarter) return settleWholeOrHalfLine(line, marginForSide);
  const lo = line - 0.25;
  const hi = line + 0.25;
  return (settleWholeOrHalfLine(lo, marginForSide) + settleWholeOrHalfLine(hi, marginForSide)) / 2;
}

function firstWord(s) {
  return String(s || '').trim().split(/\s+/)[0].toLowerCase();
}

// Reads the trailing signed line off a market label built by
// renderHandicapRow, e.g. "Asian Handicap -0.5" with prefix "Asian
// Handicap" -> -0.5. Returns null if the market doesn't start with that
// exact prefix (not this market) or carries no parseable number.
function lineFromMarket(market, prefix) {
  const m = String(market || '');
  if (!m.toLowerCase().startsWith(prefix.toLowerCase())) return null;
  const rest = m.slice(prefix.length).trim();
  const n = Number(rest);
  return Number.isFinite(n) ? n : null;
}

function settleTwoWayHandicap(market, pick, prefix, homeGoals, awayGoals) {
  const homeLine = lineFromMarket(market, prefix);
  if (homeLine == null) return null;
  const side = firstWord(pick);
  if (side !== 'home' && side !== 'away') return null;
  const line = side === 'home' ? homeLine : -homeLine;
  const marginForSide = side === 'home' ? homeGoals - awayGoals : awayGoals - homeGoals;
  const value = settleHandicapLine(line, marginForSide);
  if (value === 1) return 'won';
  if (value === -1) return 'lost';
  if (value === 0) return 'void';
  return null; // half-win/half-loss on a quarter line — not representable, leave pending
}

// "Handicap 1X2 +2" is a 3-way market (home/draw/away on the adjusted
// score) — always decided, never a push, since a draw is itself a valid
// outcome to have picked.
function settleHandicap1X2(market, pick, homeGoals, awayGoals) {
  const homeLine = lineFromMarket(market, 'Handicap 1X2');
  if (homeLine == null) return null;
  const side = firstWord(pick);
  if (side !== 'home' && side !== 'draw' && side !== 'away') return null;
  const adjusted = homeGoals + homeLine - awayGoals;
  const actual = adjusted > 0 ? 'home' : adjusted < 0 ? 'away' : 'draw';
  return side === actual ? 'won' : 'lost';
}

/**
 * Settles one bankroll bet against a real final score. `bet` is
 * `{ market, pick }` as stored by bankroll.html; `score` is
 * `{ homeGoals, awayGoals }`. Returns 'won' | 'lost' | 'void' | null —
 * null means "can't tell" (unrecognized market/pick text, a market this
 * site has no data to settle like 1st Goal or any Halftime market, or a
 * quarter-line handicap that landed on a half-state) and the bet should
 * stay untouched.
 */
function settleBet(bet, score) {
  if (!bet || !score) return null;
  const { homeGoals, awayGoals } = score;
  if (!Number.isFinite(homeGoals) || !Number.isFinite(awayGoals)) return null;
  const market = String(bet.market || '').trim();
  const pick = String(bet.pick || '').trim();
  if (!market || !pick) return null;
  const marketLower = market.toLowerCase();

  if (marketLower === '1x2' || marketLower === '1x2 (live)') {
    const side = firstWord(pick);
    if (side !== 'home' && side !== 'draw' && side !== 'away') return null;
    const actual = homeGoals > awayGoals ? 'home' : awayGoals > homeGoals ? 'away' : 'draw';
    return side === actual ? 'won' : 'lost';
  }

  if (marketLower.startsWith('o/u')) {
    const m = /^(over|under)\s+([\d.]+)$/i.exec(pick);
    if (!m) return null;
    const point = Number(m[2]);
    if (!Number.isFinite(point)) return null;
    const total = homeGoals + awayGoals;
    if (total === point) return 'void'; // SG Pools' own O/U lines are always X.5, so this shouldn't occur in practice
    const wantsOver = m[1].toLowerCase() === 'over';
    return (wantsOver && total > point) || (!wantsOver && total < point) ? 'won' : 'lost';
  }

  if (marketLower.startsWith('handicap 1x2')) return settleHandicap1X2(market, pick, homeGoals, awayGoals);
  if (marketLower.startsWith('asian handicap')) return settleTwoWayHandicap(market, pick, 'Asian Handicap', homeGoals, awayGoals);
  if (marketLower.startsWith('1/2 goal')) return settleTwoWayHandicap(market, pick, '1/2 Goal', homeGoals, awayGoals);

  if (marketLower === 'odd/even') {
    const side = pick.toLowerCase();
    if (side !== 'odd' && side !== 'even') return null;
    const isEven = (homeGoals + awayGoals) % 2 === 0;
    return (side === 'even') === isEven ? 'won' : 'lost';
  }

  if (marketLower === 'both teams to score') {
    const side = pick.toLowerCase();
    if (side !== 'yes' && side !== 'no') return null;
    const bothScored = homeGoals > 0 && awayGoals > 0;
    return (side === 'yes') === bothScored ? 'won' : 'lost';
  }

  // '1st Goal' (who scores first) and any Halftime market need data this
  // site doesn't have (only the full-time score) — never guess.
  return null;
}

// ---- fixture matching: a bet with a `matchKey` (bets logged via this
// site's own "log this bet" links since matchKey passthrough was added)
// looks itself up directly; an older or hand-typed bet falls back to
// matching its free-text fixture against a real fixture's team names,
// tolerating "vs"/"v"/"-" as the separator and requiring its date be
// within a day of the bet's own logged date (kickoff time zones/late
// kickoffs can shift the calendar day by one). ----

function normTeam(s) {
  return String(s || '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

function splitFixture(fixture) {
  const s = String(fixture || '');
  const m = /^(.+?)\s+(?:vs\.?|v)\s+(.+)$/i.exec(s) || /^(.+?)\s*-\s*(.+)$/.exec(s);
  if (!m) return null;
  const home = normTeam(m[1]);
  const away = normTeam(m[2]);
  return home && away ? { home, away } : null;
}

function dayOf(iso) {
  return String(iso || '').slice(0, 10);
}
function daysApart(dayA, dayB) {
  if (!dayA || !dayB) return Infinity;
  return Math.abs(Date.parse(dayA) - Date.parse(dayB)) / 86400000;
}

/**
 * Finds a real match's final score for one bankroll bet. `bet` is
 * `{ matchKey, fixture, date }`; `index` is
 * `{ byMatchKey: Map<matchKey, entry>, all: entry[] }` where each entry is
 * `{ matchKey, fixture, kickoffISO, score }` (the shape /api/accuracy's
 * `samples` return — a combined "Home vs Away" fixture string, not
 * separate team fields, so the fallback path below splits it the same way
 * it splits the bet's own fixture text). `score` is a "H-A" string or
 * null. Returns the entry's parsed score, or null if no confident match
 * exists yet.
 */
function findScore(bet, index) {
  if (!index) return null;
  if (bet.matchKey && index.byMatchKey.has(bet.matchKey)) {
    const entry = index.byMatchKey.get(bet.matchKey);
    return entry && entry.score ? parseScore(entry.score) : null;
  }
  const teams = splitFixture(bet.fixture);
  if (!teams) return null;
  let best = null;
  let bestDist = Infinity;
  for (const entry of index.all) {
    const eTeams = splitFixture(entry.fixture);
    if (!eTeams) continue;
    const matches =
      (eTeams.home === teams.home && eTeams.away === teams.away) ||
      (eTeams.home === teams.away && eTeams.away === teams.home);
    if (!matches) continue;
    const dist = daysApart(dayOf(entry.kickoffISO), bet.date);
    if (dist <= 1 && dist < bestDist) {
      best = entry;
      bestDist = dist;
    }
  }
  return best && best.score ? parseScore(best.score) : null;
}

const settleApi = { parseScore, settleBet, findScore, normTeam, splitFixture };
if (typeof module !== 'undefined' && module.exports) {
  module.exports = settleApi;
} else {
  (typeof window !== 'undefined' ? window : globalThis).BankrollSettle = settleApi;
}
